import{_ as a,o as i,c as n,a5 as t}from"./chunks/framework.CXroN2RO.js";const k=JSON.parse('{"title":"メモリレイアウト・パディング・アラインメント・エンディアン","description":"","frontmatter":{"title":"メモリレイアウト・パディング・アラインメント・エンディアン","study":{"source":"C++ Wiki","status":"published","summary":"実行中のプログラム(プロセス)の仮想アドレス空間は、役割ごとの領域に分かれています(配置は典型例。OSにより詳細は異なる)。 スタック: 確保はポインタをずらすだけ(超高速)。サイズ上限あり(典型1〜8MB → 深い再帰や巨大ローカル配列でstack overflow)。寿命はスコープ","section":"reference","format":"article","domain":"runtime"}},"headers":[],"relativePath":"runtime/cpp-internals/memory-layout.md","filePath":"runtime/cpp-internals/memory-layout.md"}'),l={name:"runtime/cpp-internals/memory-layout.md"};function e(p,s,r,h,o,c){return i(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="メモリレイアウト・パディング・アラインメント・エンディアン" tabindex="-1">メモリレイアウト・パディング・アラインメント・エンディアン <a class="header-anchor" href="#メモリレイアウト・パディング・アラインメント・エンディアン" aria-label="Permalink to &quot;メモリレイアウト・パディング・アラインメント・エンディアン&quot;">​</a></h1><h2 id="プロセスのメモリ地図" tabindex="-1">プロセスのメモリ地図 <a class="header-anchor" href="#プロセスのメモリ地図" aria-label="Permalink to &quot;プロセスのメモリ地図&quot;">​</a></h2><p>実行中のプログラム(プロセス)の仮想アドレス空間は、役割ごとの領域に分かれています(配置は典型例。OSにより詳細は異なる)。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高アドレス</span></span>
<span class="line"><span>┌───────────────┐</span></span>
<span class="line"><span>│ スタック(下に成長)│ ← ローカル変数、関数呼び出しのフレーム(自動記憶域)</span></span>
<span class="line"><span>│      ↓        │</span></span>
<span class="line"><span>│   (空き)      │</span></span>
<span class="line"><span>│      ↑        │</span></span>
<span class="line"><span>│ ヒープ(上に成長) │ ← new/malloc(動的記憶域)</span></span>
<span class="line"><span>├───────────────┤</span></span>
<span class="line"><span>│ .bss          │ ← ゼロ初期化のグローバル/静的変数</span></span>
<span class="line"><span>│ .data         │ ← 初期化済みグローバル/静的変数(静的記憶域)</span></span>
<span class="line"><span>│ .rodata       │ ← 定数、文字列リテラル、vtable(読み取り専用)</span></span>
<span class="line"><span>│ .text         │ ← 機械語(コード領域。読み取り+実行のみ)</span></span>
<span class="line"><span>└───────────────┘</span></span>
<span class="line"><span>低アドレス</span></span></code></pre></div><ul><li><strong>スタック</strong>: 確保はポインタをずらすだけ(超高速)。サイズ上限あり(典型1〜8MB → 深い再帰や巨大ローカル配列で<a href="/study/runtime/memory/memory-bugs.html">stack overflow</a>)。寿命はスコープ</li><li><strong>ヒープ</strong>: 任意サイズ・任意寿命。確保は管理コストあり、<a href="/study/runtime/memory/allocators-and-pools.html">断片化</a>する</li><li><strong>書けない領域に書くと</strong>OSがアクセス違反(Segmentation Fault / Access Violation)で止める——「ぬるぽで即死」の正体は大抵、低アドレス(マップされていないページ)への書き込み</li></ul><p>各領域の「寿命」の言語上の分類は、<a href="/study/runtime/memory/storage-duration-and-lifetime.html">記憶域期間と寿命</a>の項目で扱います。</p><h2 id="アラインメントとパディング" tabindex="-1">アラインメントとパディング <a class="header-anchor" href="#アラインメントとパディング" aria-label="Permalink to &quot;アラインメントとパディング&quot;">​</a></h2><p>CPUは「型のサイズの倍数のアドレス」にあるデータを効率的に(または正しく)読みます。intは4の倍数、doubleは8の倍数……これが<strong>アラインメント(整列)要求</strong>です。コンパイラは要求を満たすため、構造体に**パディング(詰め物)**を入れます。</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// C++20</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Bad</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // メンバの並びが悪い例</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           // 1バイト  (offset 0)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // パディング7    (dが8の倍数に置かれるように)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> d;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // 8バイト  (offset 8)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           // 1バイト  (offset 16)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 末尾パディング7 (配列にしたとき次の要素のdが揃うように)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    // sizeof(Bad) == 24</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Good</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // 大きい順に並べただけ</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> d;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // offset 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           // offset 8</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           // offset 9</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 末尾パディング6</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    // sizeof(Good) == 16(33%削減)</span></span></code></pre></div><p>検証済みサンプル: <a href="/study/samples/cpp/struct_layout.cpp">samples/struct_layout.cpp</a>(offsetof/sizeofでの観察)</p><ul><li>パディングの入り方は<strong>実装定義</strong>だが、上記は主要環境(x64のMSVC/GCC/Clang)の典型</li><li>大量に持つ構造体(パーティクル、ECSコンポーネント)ではサイズ=キャッシュ効率=速度。<strong>メンバは大きい順</strong>が基本テク(→ <a href="/study/game/patterns/optimization-patterns.html">Data Locality</a>)</li><li><code>alignas(16)</code> でSIMD用の16バイト整列を強制、<code>static_assert(sizeof(Particle) == 32)</code> でサイズをビルド時固定、が実務の道具</li><li><strong>バイナリ保存の罠</strong>: 構造体をそのままfwriteすると、パディング(ゴミ)込みで書かれ、コンパイラ/設定が変わると読めなくなる。シリアライズはメンバ単位で</li></ul><h2 id="エンディアン" tabindex="-1">エンディアン <a class="header-anchor" href="#エンディアン" aria-label="Permalink to &quot;エンディアン&quot;">​</a></h2><p>複数バイトの数値をメモリに置く<strong>バイト順</strong>です。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 0x12345678; をアドレスaに置くと:</span></span>
<span class="line"><span>リトルエンディアン(x86/x64, ARMの通常設定): a:[78][56][34][12] ← 下位バイトが先</span></span>
<span class="line"><span>ビッグエンディアン(ネットワークバイト順など): a:[12][34][56][78]</span></span></code></pre></div><ul><li>現代のゲーム機・PC・スマホは実質すべてリトルエンディアン。<strong>問題になるのは境界</strong>: ネットワークプロトコル(ビッグ=ネットワークバイト順の伝統)、他機種とのセーブデータ互換、バイナリフォーマットの仕様書</li><li>エンディアンは<strong>実装定義</strong>。C++20の <code>std::endian</code> でコンパイル時判定できる</li></ul><h2 id="c-との対応" tabindex="-1">C#との対応 <a class="header-anchor" href="#c-との対応" aria-label="Permalink to &quot;C#との対応&quot;">​</a></h2><ul><li>C#にも構造体レイアウトとパディングは存在する(<code>[StructLayout]</code>, <code>Marshal.SizeOf</code>)が、通常は意識しない(ランタイムが管理し、フィールド順の再配置すらする)。C++は<strong>書いた順に並ぶ</strong>(標準レイアウト型なら保証)ことが逆に道具になる</li><li>Unityで意識する瞬間: ComputeShaderへの構造体転送、NativeArray、P/Invokeの構造体マーシャリング——このページの知識がそのまま必要になる場面</li></ul><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「メモリはフラットな置き場」— 領域ごとに性質(速度・寿命・保護)が違う。スタックとヒープの確保コスト差は桁違い</li><li>「structのサイズ=メンバの合計」— パディングで増える。順序で変わる</li><li>「セーブデータはmemcpyで一発」— パディング・エンディアン・型サイズ(実装定義)の三重の罠</li></ol><h2 id="ゲーム開発での使用例" tabindex="-1">ゲーム開発での使用例 <a class="header-anchor" href="#ゲーム開発での使用例" aria-label="Permalink to &quot;ゲーム開発での使用例&quot;">​</a></h2><ul><li>パーティクル/コンポーネントのサイズ削減(並び替え、ビットフィールド、量子化)</li><li>SIMD用の <code>alignas(16)</code> 整列(→ <a href="/study/runtime/cpp-internals/cache-branch-simd.html">SIMD</a>)</li><li>ネットワークパケットの明示的レイアウト(固定幅型 <code>uint32_t</code>+エンディアン変換)</li><li>クラッシュダンプでアドレスを見て「これはスタック?ヒープ?コード?」を推定する力</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>スタックとヒープの確保コスト・寿命・サイズ上限の違いを言えますか。</li><li>パディングはなぜ入りますか。減らす基本テクは?</li><li>構造体のfwrite保存が壊れやすい理由を2つ挙げてください。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>samples/struct_layout.cpp で、(a) メンバ並び替えによるsizeof変化、(b) offsetofでパディング位置の特定、(c) 可能ならalignasの効果を確認してください。</p><hr><p>関連項目：<a href="/study/runtime/cpp-internals/exceptions-and-rtti-impl.html">RTTI・例外処理の仕組み</a> / <a href="/study/runtime/cpp-internals/">学習ガイド</a> / <a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出し・コールスタック・呼出規約</a></p>`,27)])])}const u=a(l,[["render",e]]);export{k as __pageData,u as default};
